css:
.print-heading { display: none !important; }

html, body {
    margin: 0 !important;
    padding: 0 !important;
    background: #fff;
}

@media screen {
    .print-format-gutter {
        background: #f3f3f3 !important;
        padding: 16px !important;
    }
    .print-format {
        max-width: 100% !important;
        width: 100% !important;
        min-height: 0 !important;
        padding: 20px 28px !important;
        margin: 0 auto !important;
        border-radius: 0 !important;
        box-shadow: none !important;
    }
}
.print-format { font-size: 13px !important; }
.print-format .emp-sheet table td,
.print-format .emp-sheet table th {
    padding: 0 !important;
    border: none !important;
}
.print-format .emp-sheet img { max-width: none !important; }

.emp-sheet {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Inter, Arial, sans-serif;
    color: #1f272e;
    font-size: 13px;
    width: 100%;
    box-sizing: border-box;
}

.emp-top {
    width: auto;
    border-collapse: collapse;
    margin-bottom: 22px;
}
.print-format .emp-sheet .emp-top td {
    border: none !important;
    vertical-align: middle !important;
    padding: 0 !important;
}
.emp-photo, .emp-photo-empty {
    width: 150px;
    height: 150px;
    border-radius: 6px;
    background: #f3f3f3;
    border: 1px solid #e5e5e5;
}
.emp-photo { object-fit: cover; display: block; }
.emp-photo-empty {
    text-align: center;
    color: #9ca3af;
    font-size: 12px;
    line-height: 150px;
}
.emp-headline {
    font-size: 22px;
    font-weight: 700;
    margin: 0 0 4px;
    letter-spacing: -0.02em;
    line-height: 1.2;
}
.emp-meta { font-size: 13px; color: #6b7280; margin: 0; }
.emp-pill {
    display: inline-block;
    margin-left: 10px;
    padding: 2px 10px;
    border-radius: 999px;
    font-size: 12px;
    font-weight: 600;
    vertical-align: middle;
}
.emp-pill-on { background: #e4f5e9; color: #16794c; }
.emp-pill-off { background: #fcebeb; color: #b52a2a; }

.emp-section { margin-bottom: 18px; }
.emp-section-title {
    font-size: 13px;
    font-weight: 600;
    color: #4c5a67;
    background: #f4f5f6;
    padding: 8px 12px;
    margin-bottom: 12px;
    border-radius: 4px;
}

.emp-grid {
    width: 100%;
    border-collapse: separate;
    border-spacing: 16px 10px;
    margin: -10px -16px;
}
.emp-grid td {
    width: 50%;
    vertical-align: top;
    border: none !important;
    padding: 0 !important;
}
.emp-label {
    display: block;
    font-size: 12px;
    color: #6b7280;
    margin-bottom: 4px;
}
.emp-box {
    background: #f4f5f6;
    border-radius: 6px;
    padding: 8px 12px;
    min-height: 20px;
    color: #1f272e;
    font-size: 13px;
    line-height: 1.4;
    word-wrap: break-word;
}
.emp-box-empty { color: #c0c4c8; }

@media print {
    html, body { background: #fff !important; }
    .print-format {
        max-width: 100% !important;
        min-height: 0 !important;
        padding: 0 !important;
    }
}
